out=[]
for id,pmid,short,design,topic,population,exposure,signal,finding,result,limits,guide in rows:
 r=records[pmid]
 out.append(dict(id=id,pmid=pmid,title=short,originalTitle=r['title'].rstrip('.'),authors=r['authorString'],year=int(r['pubYear']),doi=r['doi'],journal=r.get('journalInfo',{}).get('journal',{}).get('title',''),design=design,topic=topic,population=population,exposure=exposure,signal=signal,finding=finding,result=result,limitations=limits,guide=guide,url='https://pubmed.ncbi.nlm.nih.gov/'+pmid+'/',fullText=('https://pmc.ncbi.nlm.nih.gov/articles/'+r['pmcid']+'/') if r.get('pmcid') else 'https://doi.org/'+r['doi'],sourceLevel='Abstract checked',checked='2026-10-07'))
Path('lib/studies.ts').write_text('export type Study = '+'''{id:string;pmid:string;title:string;originalTitle:string;authors:string;year:number;doi:string;journal:string;design:string;topic:string;population:string;exposure:string;signal:string;finding:string;result:string;limitations:string;guide:string;url:string;fullText:string;sourceLevel:string;checked:string};\n'''+'export const studies:Study[] = '+json.dumps(out,ensure_ascii=False,indent=2)+';\n')
print('Wrote',len(out),'verified study records')
